insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d4126286-092d-4c3e-a4f6-010ad42043b3', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Una estudiante aplica dos fuerzas de igual magnitud en distintas partes a cuatro barras, como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q97-barras.webp" loading="lazy" alt="Cuatro barras horizontales, cada una con su centro de masa marcado en el punto medio. En la barra 1, F1 apunta hacia abajo en el extremo derecho y F2 hacia arriba en el extremo izquierdo. En la barra 2, F2 apunta hacia abajo en el extremo izquierdo y F1 hacia abajo en el derecho. En la barra 3, F1 apunta hacia abajo en el extremo izquierdo y F2 hacia arriba en el derecho. En la barra 4, F1 hacia abajo y F2 hacia arriba, las dos sobre el mismo extremo derecho."></figure><p>El estudiante sabe que dependiendo de dónde se apliquen las fuerzas en las barras, estas pueden rotar respecto al centro de masa, moverse sin rotar o permanecer quietas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('aacedfe6-d274-45b5-82df-c4d2bb8e262d', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un paracaidista se lanza de un avión y registra su rapidez de caída en función del tiempo en la siguiente gráfica.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q98-grafica.webp" loading="lazy" alt="Gráfica original de rapidez frente al tiempo: la rapidez aumenta durante los primeros segundos y alcanza una meseta de 40 m/s."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f404b3a3-7845-466a-bf34-a3e5dac0f71a', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante modela el flujo de calor entre dos objetos (P y Q), a partir de una analogía con el movimiento del agua contenida en dos recipientes.</p><p>El estudiante observa que cuando se conectan dos recipientes con niveles y cantidades de agua diferentes (ver figura), el agua se mueve del recipiente P al recipiente Q, hasta que los dos recipientes tienen el mismo nivel de agua.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q99-recipientes.webp" loading="lazy" alt="Dos recipientes comunicados por un tubo en la base. El recipiente P es angosto y su nivel de agua es alto; el recipiente Q es ancho y su nivel es más bajo. Una línea punteada marca el nivel del agua en P, por encima del nivel de Q."></figure><p>En el modelo, el nivel del líquido representará la temperatura y la cantidad de líquido representará la energía térmica (que se puede transferir como calor).</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('65f1e592-8950-4696-b8e7-5389213e787a', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un grupo de estudiantes pretende verificar las características del movimiento rectilíneo uniforme. Para ello, los estudiantes establecen una distancia fija que va a mover un carrito, luego realizan 3 mediciones del tiempo que emplea el carrito para recorrerla. Estos tiempos se promedian, y la distancia se divide entre ese valor para calcular un indicador de velocidad.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ccfaca75-6332-4828-a23a-f945b1ea2fd2', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante coloca un recipiente con agua caliente junto con otro con agua fría; a través de las paredes de los recipientes se establecerá un flujo de energía calorífica y, pasado un tiempo, estos llegarán a un equilibrio térmico con el ambiente (ver Figura 1).</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q101-equilibrio.webp" loading="lazy" alt="Figura 1: dos recipientes contiguos, uno con agua caliente y otro con agua fría, con flechas de flujo de calor que salen del agua caliente hacia el agua fría y hacia el exterior. Figura 2: los mismos dos recipientes, ahora encerrados dentro de una caja de icopor sellada."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('80046023-bc8b-4ffd-a42a-d549afbdf0e6', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Una estudiante lee que el torque se da cuando se aplica una fuerza en algún punto de un cuerpo y este tiende a realizar un movimiento de rotación respecto a otro punto. La estudiante analiza que cuando una persona monta en bicicleta ejerce una fuerza (F) en el pedal hacia abajo, como muestra la figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q102-bicicleta.webp" loading="lazy" alt="Ciclista sobre una bicicleta. Una ampliación señala el manubrio, la cadena y el plato; sobre el pedal se dibuja la fuerza F apuntando hacia abajo."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('88c137f8-ea2d-4528-99ab-2ac4c7542548', 'situacion', 'FÍSICA', 'ctx-sit', '<p>En un experimento se tomaron medidas de la variación del volumen (ΔV) de un cubo de un material elástico (respecto a un volumen de referencia), de su temperatura (T) y de la presión (P) a la que se sometía. Los datos del experimento se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><tr><th>P (atm)</th><th colspan="4"></th></tr><tr><td rowspan="2">1,0</td><td>T (°C)</td><td>32</td><td>35</td><td>40</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>1,1</td><td>1,6</td><td>1,9</td></tr><tr><td rowspan="2">1,1</td><td>T (°C)</td><td>31</td><td>36</td><td>39</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>0,9</td><td>1,2</td><td>1,4</td></tr><tr><td rowspan="2">1,3</td><td>T (°C)</td><td>29</td><td>33</td><td>38</td></tr><tr><td>ΔV (cm<sup>3</sup>)</td><td>0,7</td><td>0,8</td><td>1,0</td></tr></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8cc31f9e-448f-46e5-af9d-44acd76c08de', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un dinamómetro es un instrumento que se utiliza para medir fuerzas. Cuanto más se estira el resorte del dinamómetro, mayor es la fuerza que se ejerce sobre este. En la siguiente figura se muestra un dinamómetro en dos situaciones. En la primera, un objeto atado al dinamómetro cuelga en el aire y en la segunda, el objeto está sumergido en agua.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q104-dinamometro.webp" loading="lazy" alt="Dos dinamómetros de resorte. En la situación 1 el resorte, más estirado, sostiene un bloque colgando en el aire. En la situación 2 el mismo bloque cuelga sumergido dentro de un recipiente con agua y el resorte aparece menos estirado."></figure><p>Los estudiantes notan que la fuerza registrada por el dinamómetro es menor en la situación 2 que en la situación 1.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ca09125f-921d-4f0c-81a7-516d7b9d89b6', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Se lanzan tres pelotas, L, M y N, desde la azotea de un edificio de 30 m de altura. La siguiente gráfica muestra la altura de las pelotas como función del tiempo.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q105-grafica.webp" loading="lazy" alt="Gráfica original de altura frente al tiempo. L es la curva punteada, M la discontinua y N la continua; las tres llegan al eje de altura cero."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9878b5e8-f5ea-496f-9bd0-ad83292f8a3d', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un vuelo comercial, que transporta aproximadamente 500 pasajeros por vuelo, maneja una tabla como la siguiente para calcular el combustible necesario en cada trayecto.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Kilómetros</th><th>Litros</th></tr><tr><td>1,6</td><td>19</td></tr><tr><td>3,2</td><td>38</td></tr><tr><td>4,8</td><td>57</td></tr><tr><td>6,4</td><td>76</td></tr></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('994a5607-698c-43d1-9a6c-e2ab945d41f1', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Cuando una ola se acerca a la costa, se puede representar su movimiento como una onda (ver figura).</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q107-ola.webp" loading="lazy" alt="Corte vertical del mar acercándose a la costa. El fondo asciende desde la izquierda, donde el agua es profunda, hasta la costa, a la derecha, donde es somera. Una flecha punteada indica el sentido de avance de la ola hacia la costa."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('74abc147-4792-48c0-9971-62f44ad9469a', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Una grúa levanta una caja de masa (m), como se muestra en la Figura 1.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q108-grua.webp" loading="lazy" alt="Figura 1: una grúa con su pluma sostiene una caja rotulada m, colgada de un cable."></figure><p>El funcionamiento de la grúa puede modelarse como una máquina de Atwood. En este modelo, como lo muestra la Figura 2, se aplica una fuerza F<sub>motor</sub> sobre una cuerda que produce, sobre esta, una tensión T, con la finalidad de levantar un cuerpo de peso mg.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q108-atwood.webp" loading="lazy" alt="Figura 2: una polea con una cuerda. De un lado cuelga un bloque de peso mg, sobre el que la cuerda ejerce una tensión T hacia arriba. Del otro lado de la polea se tira de la cuerda con la fuerza F del motor, dirigida hacia abajo."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d29da8fe-9285-4e8a-b25b-e5b633770b54', 'situacion', 'FÍSICA', 'ctx-sit', '<p>La expansión térmica es el fenómeno físico que experimenta un cuerpo al calentarse. Conforme aumenta la temperatura del objeto aumenta su tamaño, y sus cambios de longitud son proporcionales a los cambios de temperatura.</p><p>Un alambre de cobre de longitud inicial de 1,00000 metros a una temperatura de 20 °C se calienta hasta alcanzar los 50 °C y llega a una longitud final de 1,00051 metros.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('087e8897-b2ae-4cbb-86ad-c42af61f8e52', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Una estudiante suelta dos hojas de papel iguales desde la misma altura. Sin embargo, una está arrugada y la otra no. La estudiante mide los tiempos de caída y los organiza en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><tr><th></th><th>Tiempo I (s)</th><th>Tiempo II (s)</th><th>Tiempo III (s)</th><th>Tiempo promedio (s)</th></tr><tr><td>Hoja arrugada</td><td>0,30</td><td>0,40</td><td>0,40</td><td>0,36</td></tr><tr><td>Hoja lisa</td><td>1,10</td><td>1,10</td><td>1,10</td><td>1,06</td></tr></table></div><p>A partir de lo anterior, la estudiante afirma que las dos hojas caen debido a la fuerza de atracción gravitacional que ejerce la Tierra sobre estas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('62c785e8-8dd5-41d9-9a6e-d0d4e47df94f', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante ubica una sombrilla sobre un ventilador soplando hacia arriba y observa que la sombrilla comienza a aumentar su velocidad hacia arriba, como se muestra en la figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q111-sombrilla.webp" loading="lazy" alt="El dibujo muestra una sombrilla abierta y un ventilador que sopla hacia arriba, representados uno junto al otro. El enunciado describe la sombrilla situada sobre el ventilador."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('5e9408e5-0899-4636-857e-1fbb1dc7af9c', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante observa que cuando llueve intensamente caen gotas de agua congeladas a una velocidad de 40 km/h. Una de estas gotas choca con el piso y cambia su dirección de movimiento. En las figuras 1 y 2 se muestran las fuerzas que actúan sobre la gota antes y durante el choque respectivamente.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q112-choque.webp" loading="lazy" alt="Figura 1, antes del choque: sobre la gota que cae se dibujan la resistencia del aire, la fuerza del viento y el peso, este último hacia abajo. Figura 2, durante el choque: la gota está en contacto con el piso y sobre ella se dibujan el peso hacia abajo y la normal hacia arriba."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e147c394-d5a1-468d-a6f2-29b850e377ca', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante viaja a un lago que es famoso porque es muy difícil hundirse en él. Cuando el estudiante llega a un lugar donde la profundidad es de 4 metros e intenta sumergirse, se da cuenta de que requiere mucha energía para hundirse en sus aguas y que puede flotar en ellas sin ningún esfuerzo, cosa que no pasa en una piscina, donde el estudiante se hunde más rápido.</p><p>Cuando él observa con cuidado el agua de este lago, se da cuenta de que tiene un color amarillento, un olor muy fuerte y un sabor bastante particular.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('72db55ba-ede8-4cd3-946c-d74bc2f58e6e', 'situacion', 'FÍSICA', 'ctx-sit', '<p>El sistema que muestra la figura consta de una cubeta dividida en dos secciones por una membrana sensible: la parte izquierda está llena de agua y la derecha contiene aceite. Una esfera hueca colgada de una cuerda de 2,5 m de longitud oscila por encima de la cubeta y al pasar por el punto más bajo roza con el agua formando ondas.</p><figure class="ctx-fig"><img src="img/figuras/fis/f1-q114-cubeta.webp" loading="lazy" alt="Cubeta rectangular dividida en dos mitades por una membrana sensible: la mitad izquierda contiene agua y la derecha aceite. Sobre ella cuelga, de un soporte, una esfera sujeta por una cuerda, que oscila y al pasar por el punto más bajo toca la superficie del agua generando ondas circulares."></figure><p><b>Nota:</b> suponga que el péndulo oscila con frecuencia constante sin tener en cuenta las pérdidas de energía por fricción.</p>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '70100228-e59a-44f3-a1ae-a73f0f53c585', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'd4126286-092d-4c3e-a4f6-010ad42043b3', 'Dinámica y fuerzas',
  '¿En qué barra la aplicación de las fuerzas produce que la barra gire en el sentido opuesto al de las manecillas del reloj?',
  array['En la barra 1.', 'En la barra 2.', 'En la barra 3.', 'En la barra 4.'],
  'Mira a qué lado del centro actúa cada fuerza y hacia dónde apunta: el giro lo decide esa combinación, no la magnitud.', 'publicada', 'modelo', 'bbf791b2a90ab073993b5fd8f45ede6a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('70100228-e59a-44f3-a1ae-a73f0f53c585', 2, 'Un par de fuerzas hace girar la barra cuando empujan en sentidos contrarios a lados distintos del centro. En la barra 3 la fuerza de la izquierda baja y la de la derecha sube: el extremo izquierdo cae y el derecho asciende, que es el giro contrario al del reloj. En la barra 1 pasa lo mismo pero al revés, y gira con el reloj. En la barra 2 las dos fuerzas bajan, así que la barra desciende sin girar, y en la barra 4 ambas actúan sobre el mismo punto y se anulan.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0f58a0ea-65a7-4694-a395-4cae4a8fe484', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'cinematica'),
  (select id from public.lotes where codigo = '2026-B'),
  'aacedfe6-d274-45b5-82df-c4d2bb8e262d', 'Cinemática',
  'A partir de la información anterior, luego de 7 segundos el paracaidista',
  array['aumenta su rapidez.', 'mantiene su rapidez en 0 m/s.', 'disminuye su rapidez.', 'mantiene su rapidez en 40 m/s.'],
  'En una gráfica de rapidez contra tiempo lo que importa es la inclinación: plana es rapidez constante, no rapidez cero.', 'publicada', 'modelo', 'f76742c4ae7a5690f3dce5679cb5da90', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0f58a0ea-65a7-4694-a395-4cae4a8fe484', 3, 'Después de los primeros segundos la curva deja de subir y se vuelve horizontal a la altura de 40 en el eje vertical. Una gráfica plana significa rapidez constante: a los 7 segundos, y de ahí en adelante, el paracaidista cae siempre a 40 metros por segundo. Es la rapidez límite, cuando la resistencia del aire iguala al peso.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '283748a0-61e0-45ac-ba00-0efbb96eb285', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'f404b3a3-7845-466a-bf34-a3e5dac0f71a', 'Termodinámica',
  'Según el modelo, si se colocan dos objetos de diferentes tamaños (Volumen<sub>Q</sub> &gt; Volumen<sub>P</sub>) y temperaturas (Temperatura<sub>P</sub> &gt; Temperatura<sub>Q</sub>), ¿cómo será el flujo de calor?',
  array['De Q a P, porque fluiría del cuerpo con mayor calor al cuerpo con menor calor.', 'De P a Q, porque fluiría del cuerpo con mayor temperatura al cuerpo con menor temperatura.', 'De P a Q, porque fluiría del cuerpo con menor temperatura al cuerpo con mayor temperatura.', 'De Q a P, porque fluiría del cuerpo con menor calor al cuerpo con mayor calor.'],
  'Separa «cuánta energía tiene un cuerpo» de «qué tan caliente está»: lo que decide hacia dónde va el calor es lo segundo.', 'publicada', 'modelo', 'b3610023b3fdb157f0c52f653957e342', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('283748a0-61e0-45ac-ba00-0efbb96eb285', 1, 'En la analogía el agua no se mueve hacia donde hay más agua, sino hacia donde el nivel es más bajo: en la figura P está más alto aunque Q contenga más líquido. Como el nivel representa la temperatura, el calor va del objeto más caliente al más frío. P tiene mayor temperatura, así que el calor fluye de P a Q, aunque Q sea más grande y guarde más energía térmica.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f1220c8b-140b-41e3-8c66-7224e614fc13', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'cinematica'),
  (select id from public.lotes where codigo = '2026-B'),
  '65f1e592-8950-4696-b8e7-5389213e787a', 'Cinemática',
  'Teniendo en cuenta la información anterior, ¿cuál de las siguientes carteleras, con secuencias, muestra correctamente el procedimiento efectuado por los estudiantes?',
  array['<figure class="ctx-fig"><img src="img/figuras/fis/f1-q100-a.webp" loading="lazy" alt="Secuencia: medir distancia, luego medir tiempos, luego promediar tiempos, luego dividir distancia entre tiempos promedio y por último calcular indicador de velocidad."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f1-q100-b.webp" loading="lazy" alt="Secuencia que arranca en medir tiempos y va hacia medir distancia; de medir tiempos baja a calcular indicador de velocidad, que lleva a dividir distancia entre tiempos promedio y de ahí sube a promediar tiempos."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f1-q100-c.webp" loading="lazy" alt="Secuencia que arranca en medir tiempos y va hacia medir distancia; de medir tiempos sigue a promediar tiempos y baja a dividir distancia entre tiempos promedio; calcular indicador de velocidad apunta hacia medir distancia."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f1-q100-d.webp" loading="lazy" alt="Secuencia: medir distancia baja a calcular indicador de velocidad, que lleva a medir tiempos, que sube a dividir distancia entre tiempos promedio y de ahí a promediar tiempos."></figure>'],
  'Lee el procedimiento como una receta y numera los pasos; después busca la cartelera cuyas flechas siguen esa numeración sin saltos.', 'publicada', 'modelo', '573a0cf3a4031a549a054e66219428df', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f1220c8b-140b-41e3-8c66-7224e614fc13', 0, 'El enunciado describe un orden que no se puede alterar: primero se fija la distancia, después se cronometra tres veces, luego se promedian esos tiempos, y solo entonces se divide la distancia entre el promedio para obtener la velocidad. La cartelera correcta es la única que encadena los cinco pasos en ese orden y termina en el cálculo del indicador. Las demás invierten flechas o ponen el cálculo antes de tener los datos, es decir, dividen antes de haber promediado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ed766029-ffb3-4424-973b-4e531d30d1cb', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'ccfaca75-6332-4828-a23a-f945b1ea2fd2', 'Termodinámica',
  'Con base en el modelo de equilibrio térmico planteado con anterioridad, ¿qué pasará si los dos recipientes se dejaran aislados dentro de una caja de icopor sellada (ver Figura 2) a una temperatura intermedia entre el agua caliente y la fría?',
  array['Aumentará únicamente la temperatura del agua caliente, porque en los sitios cerrados el que cede la energía es el cuerpo con menor temperatura.', 'Disminuirá la temperatura del agua caliente y de la fría, y aumentará la temperatura de la caja, porque el medio absorbe toda la energía del agua.', 'Disminuirá únicamente la temperatura del agua fría, porque en sitios cerrados el cuerpo que cede energía es el cuerpo con la menor temperatura.', 'Aumentará la temperatura del agua fría, porque el cuerpo con mayor temperatura siempre cede energía a los cuerpos más fríos.'],
  'En un recinto aislado nada se pierde: lo que un cuerpo cede, otro lo recibe. Pregúntate quién cede y quién recibe.', 'publicada', 'modelo', '11c7b746ec1eb0b77c97983eed029e2d', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ed766029-ffb3-4424-973b-4e531d30d1cb', 3, 'El calor siempre va del cuerpo más caliente al más frío, dentro o fuera de una caja. Al aislarlos, el agua caliente se enfría y la fría se calienta hasta que las dos igualan la temperatura. Las opciones que hacen ceder energía al cuerpo más frío invierten esa regla, y la que enfría las dos aguas a la vez no puede ser: si ambas bajaran de temperatura, esa energía no tendría a dónde ir dentro de una caja sellada.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7c12912f-f8ee-4be4-9fec-5d99dd2f3434', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '80046023-bc8b-4ffd-a42a-d549afbdf0e6', 'Dinámica y fuerzas',
  'Si el estudiante quiere medir el torque que permite el desplazamiento de la bicicleta, ¿cuál de los siguientes puntos de la bicicleta es el más adecuado para hacerlo?',
  array['El extremo inferior de la cadena.', 'El centro de la rueda delantera.', 'El centro del plato.', 'El centro del manubrio.'],
  'Para hablar de torque hace falta un eje de giro. Busca alrededor de qué punto gira exactamente aquello sobre lo que se aplica la fuerza.', 'publicada', 'modelo', '29800cd8dd0d8b3732d436f9ce1b0620', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7c12912f-f8ee-4be4-9fec-5d99dd2f3434', 2, 'El torque se mide respecto al punto alrededor del cual gira el cuerpo sobre el que se aplica la fuerza. La fuerza del pie actúa sobre el pedal, y el pedal gira alrededor del eje del plato: ese es el centro de giro que corresponde. La cadena no es un punto de rotación sino lo que transmite el movimiento, y ni la rueda delantera ni el manubrio reciben la fuerza del pedaleo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5437b23b-4fb6-411e-9029-ad5992ef23ef', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '88c137f8-ea2d-4528-99ab-2ac4c7542548', 'Termodinámica',
  'Teniendo en cuenta la información anterior, ¿cuál de los siguientes sería el título más apropiado para esta tabla?',
  array['Variación del volumen con la temperatura a diferentes presiones.', 'Comportamiento de la temperatura y el volumen a diferentes presiones.', 'Comportamiento de la temperatura con la presión a diferentes volúmenes.', 'Variación del volumen y la presión a diferentes temperaturas.'],
  'En una tabla, distingue qué se fija, qué se hace variar y qué se mide. El título se escribe en ese orden.', 'publicada', 'modelo', '954d65316cd91ab21b663b07af7ecaa4', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5437b23b-4fb6-411e-9029-ad5992ef23ef', 0, 'La tabla tiene tres presiones fijas, y dentro de cada una se anotan parejas de temperatura y variación de volumen. Es decir, la presión es la condición que se mantiene constante en cada bloque, la temperatura es lo que se hace variar y el volumen es lo que se mide como respuesta. Un título fiel tiene que decir eso: cómo cambia el volumen con la temperatura, y que se repitió a varias presiones. Los otros títulos cambian de lugar cuál variable se mide y cuál se controla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a3046dd2-69d0-42e2-9da9-319816244210', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '8cc31f9e-448f-46e5-af9d-44acd76c08de', 'Dinámica y fuerzas',
  '¿Cuál es la fuerza que hace que ocurra esto?',
  array['La fricción.', 'La normal.', 'El empuje.', 'El peso.'],
  'Si un cuerpo pesa lo mismo pero el instrumento marca menos, es que apareció otra fuerza empujando hacia arriba.', 'publicada', 'modelo', '43c219360a9b595cd1207e40e0a58b28', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a3046dd2-69d0-42e2-9da9-319816244210', 2, 'El peso del objeto no cambió al meterlo en el agua: sigue teniendo la misma masa. Lo que aparece es una fuerza hacia arriba que el líquido ejerce sobre el cuerpo sumergido, el empuje, y que ayuda al resorte a sostenerlo. Como el resorte tiene que hacer menos fuerza, se estira menos y el dinamómetro marca menos. La normal aparece cuando un cuerpo se apoya en una superficie, y la fricción cuando hay deslizamiento; aquí el cuerpo cuelga.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9252d69f-3918-461d-a183-f4c1bc833456', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'cinematica'),
  (select id from public.lotes where codigo = '2026-B'),
  'ca09125f-921d-4f0c-81a7-516d7b9d89b6', 'Cinemática',
  'Teniendo en cuenta la información de la gráfica, ¿en qué orden llegan las pelotas al piso?',
  array['Primero L, después N y por último M.', 'Primero N, después M y por último L.', 'Primero M, después L y por último N.', 'Primero L, después M y por último N.'],
  'No mires qué tan alto llega cada una: mira en qué instante cada curva llega a altura cero.', 'publicada', 'modelo', '4fc3f277ad497685a38b23a83bb0a47b', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9252d69f-3918-461d-a183-f4c1bc833456', 3, 'Llegar al suelo corresponde a alcanzar altura cero. Lee dónde cada curva toca el eje del tiempo: L lo hace primero, M después y N al final. La altura inicial es la misma, pero las velocidades iniciales son distintas; por eso no llegan simultáneamente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'e6422d4f-3762-4ec5-8f41-b75ab7114bf8', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'cinematica'),
  (select id from public.lotes where codigo = '2026-B'),
  '9878b5e8-f5ea-496f-9bd0-ad83292f8a3d', 'Cinemática',
  'A partir de la información anterior, ¿cuáles serían los títulos apropiados para las columnas de la tabla, respectivamente?',
  array['Área y volumen.', 'Distancia y tipo de combustible.', 'Cantidad de personas y volumen.', 'Distancia y volumen.'],
  'Antes de elegir, pregúntate qué magnitud mide cada unidad: el kilómetro y el litro no miden lo mismo.', 'publicada', 'modelo', '67093d5d900a5b49aa44314ecf0c1416', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e6422d4f-3762-4ec5-8f41-b75ab7114bf8', 3, 'Hay que fijarse en qué mide cada unidad. El kilómetro mide longitud recorrida, o sea distancia; el litro mide capacidad, o sea volumen. Los 500 pasajeros aparecen en el enunciado pero no en la tabla, y el tipo de combustible sería un nombre, no un número. El área se mediría en unidades al cuadrado, que no es el caso.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a24cfcbf-33ff-4f5e-b116-fb82909c1a41', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'ondas-y-sonido'),
  (select id from public.lotes where codigo = '2026-B'),
  '994a5607-698c-43d1-9a6c-e2ab945d41f1', 'Ondas y sonido',
  'Si la amplitud de una onda se entiende como la altura que tienen sus puntos más altos, ¿cómo cambia la amplitud de la ola a medida que se acerca a la costa?',
  array['Aumenta a medida que aumenta la profundidad.', 'Es constante para cualquier profundidad.', 'Aumenta a medida que se reduce la profundidad.', 'Disminuye a medida que disminuye la profundidad.'],
  'Sigue el fondo en la figura: la respuesta depende de qué le pasa a la profundidad, no de qué le pasa a la distancia.', 'publicada', 'modelo', '72b2f0ff3dd113d2698e7734525a52e0', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a24cfcbf-33ff-4f5e-b116-fb82909c1a41', 2, 'La figura muestra que el fondo sube conforme la ola se acerca a la costa, así que la profundidad disminuye. Al tener menos agua debajo, la ola se frena y la energía que traía se acumula en menos espacio: la ola se encrespa y sus crestas se vuelven más altas. Por eso las olas rompen cerca de la orilla y no en mar abierto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c886b235-5c22-462a-ac93-58013f9c2ac6', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '74abc147-4792-48c0-9971-62f44ad9469a', 'Dinámica y fuerzas',
  '¿Qué predicción puede hacerse a partir del modelo?',
  array['F<sub>motor</sub> está dirigida en sentido contrario al peso.', 'Para levantar la caja, se necesitará que la magnitud de T sea mayor que su peso.', 'Es posible levantar la caja si la magnitud de T es menor que el peso de la caja.', 'La grúa levantará la caja sin importar la magnitud de F<sub>motor</sub>.'],
  'Para que un cuerpo arranque hacia arriba, la suma de fuerzas debe apuntar hacia arriba. Compara la tensión con el peso.', 'publicada', 'modelo', 'ebe98ba250fc5a93b8515b9e11484d91', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c886b235-5c22-462a-ac93-58013f9c2ac6', 1, 'Para que la caja arranque hacia arriba desde el reposo, la fuerza neta debe apuntar hacia arriba: T − mg debe ser positiva y, por tanto, T debe superar al peso. Si T = mg no hay aceleración: la caja puede permanecer quieta o moverse con velocidad constante. La fuerza del motor dibujada al otro lado de la polea apunta hacia abajo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'da348fca-e6dc-4508-9e73-08577b6649ec', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'd29da8fe-9285-4e8a-b25b-e5b633770b54', 'Termodinámica',
  '¿Cuál de las siguientes gráficas de longitud como función de la temperatura describe la situación anterior?',
  array['<figure class="ctx-fig"><img src="img/figuras/fis/f1-q109-a.webp" loading="lazy" alt="Gráfica de longitud contra temperatura: una recta que sube de manera uniforme desde 1,00000 metros a los 20 grados hasta 1,00051 metros a los 50 grados."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f1-q109-b.webp" loading="lazy" alt="Gráfica de longitud contra temperatura: una curva que se mantiene casi plana en 1,00000 metros y solo al final, cerca de los 50 grados, se dispara hacia arriba."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f1-q109-c.webp" loading="lazy" alt="Gráfica de longitud contra temperatura: una recta que arranca por debajo de 1,00000 metros antes de los 20 grados y sube con más inclinación, superando 1,00051 antes de llegar a los 50 grados."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f1-q109-d.webp" loading="lazy" alt="Gráfica de longitud contra temperatura: una curva que sube muy rápido al principio y después se aplana, quedando casi horizontal en 1,00051 metros."></figure>'],
  'Traduce «proporcional» a una forma: es una recta. Después comprueba que pase por los dos valores que da el texto.', 'publicada', 'modelo', '22b0dbabef819e213510d284e01b52a4', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('da348fca-e6dc-4508-9e73-08577b6649ec', 0, 'El enunciado dice que los cambios de longitud son proporcionales a los cambios de temperatura. Proporcional significa que a cada grado que sube corresponde siempre el mismo estiramiento, y eso en una gráfica es una línea recta. Además la recta debe salir de 1,00000 a los 20 grados y llegar a 1,00051 a los 50, que son los dos datos medidos. Las curvas no sirven porque en ellas el estiramiento por grado cambia según el tramo, y la recta que no pasa por los dos puntos medidos tampoco.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '2f45b0c7-9b74-4042-a0c2-24fdad4d9663', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'cinematica'),
  (select id from public.lotes where codigo = '2026-B'),
  '087e8897-b2ae-4cbb-86ad-c42af61f8e52', 'Cinemática',
  '¿Qué tipo de afirmación es la anterior?',
  array['Una hipótesis, porque se ajusta a los datos (masa, tiempo, volumen) tomados durante la observación.', 'Una suposición no fundamentada, porque no tiene en cuenta las mediciones.', 'Una hipótesis, porque intenta explicar por qué la hoja arrugada cae más rápido.', 'Una suposición no fundamentada, porque es una ley científicamente reconocida.'],
  'Compara la afirmación con lo que las mediciones muestran. Si la afirmación sería la misma sin haber medido, no se apoya en los datos.', 'publicada', 'modelo', 'bb4eb1ce894a6dd82dfa42b8768246c0', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2f45b0c7-9b74-4042-a0c2-24fdad4d9663', 1, 'Lo que la estudiante midió fue una diferencia: la hoja arrugada cae en un tercio del tiempo que la lisa. Decir que las dos caen por la gravedad es cierto, pero no dice nada sobre esa diferencia, que es justo lo que el experimento sacó a la luz. Una afirmación que ignora los datos recogidos no se apoya en ellos. Tampoco explica por qué una cae más rápido, porque la gravedad actúa igual sobre las dos; lo que las distingue es la resistencia del aire.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '63730b58-b4c9-490e-aa26-ba2d996a3d37', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '62c785e8-8dd5-41d9-9a6e-d0d4e47df94f', 'Dinámica y fuerzas',
  '¿Cómo debe ser la fuerza que ejerce el aire del ventilador para que la sombrilla se mueva aceleradamente hacia arriba?',
  array['Menor que el peso de la sombrilla.', 'Mayor que el peso de la sombrilla.', 'Igual al peso de la sombrilla.', 'Igual al peso del ventilador.'],
  'Acelerar en un sentido exige que la suma de fuerzas apunte en ese sentido. Compara solo las fuerzas que actúan sobre la sombrilla.', 'publicada', 'modelo', '8c959f56da5fd06d6c4d364b01c1c164', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('63730b58-b4c9-490e-aa26-ba2d996a3d37', 1, 'Sobre la sombrilla actúan el aire, que la empuja hacia arriba, y su propio peso, que tira hacia abajo. Si las dos fuerzas fueran iguales la sombrilla quedaría suspendida sin acelerar, y si el aire hiciera menos fuerza caería. Como el enunciado dice que va aumentando su velocidad hacia arriba, la fuerza del aire tiene que superar al peso. El peso del ventilador no interviene: no es un cuerpo que esté sobre la sombrilla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1cccbc53-f576-4e3f-8d20-6ddf1abef3cc', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '5e9408e5-0899-4636-857e-1fbb1dc7af9c', 'Dinámica y fuerzas',
  'Teniendo en cuenta la información anterior, ¿cuál es la fuerza que hace que la gota cambie de dirección?',
  array['La fuerza del viento.', 'La fuerza normal.', 'El peso de la gota.', 'La fuerza de rozamiento.'],
  'Fíjate en qué sentido cambió el movimiento y busca, entre las fuerzas dibujadas en ese instante, la que apunta hacia allá.', 'publicada', 'modelo', 'ceeb1e3d5c7e36d7dd229c22dcdb183e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1cccbc53-f576-4e3f-8d20-6ddf1abef3cc', 1, 'Antes de tocar el piso la gota baja, y después del choque sube: su movimiento se invirtió, y eso solo puede hacerlo una fuerza dirigida hacia arriba. La única que aparece en la figura del momento del choque y apunta hacia arriba es la normal, la que el piso ejerce sobre todo lo que se apoya en él. El peso apunta hacia abajo, así que no puede devolverla, y el viento y el rozamiento actuaban durante la caída, no en el rebote.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7f203498-c719-48b4-8f98-11e0d5f28bde', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'e147c394-d5a1-468d-a6f2-29b850e377ca', 'Dinámica y fuerzas',
  'De acuerdo con lo anterior, ¿cuál de las siguientes hipótesis plantea una causa probable para explicar por qué en este lago se flota con mayor facilidad que en una piscina?',
  array['Este lugar es tan poco profundo que es imposible hundirse en él, ya que el agua le llega a las rodillas al estudiante.', 'El agua de este lago contiene compuestos químicos que aumentan su densidad y facilitan la flotabilidad.', 'El agua de este lago es potable, pero el agua de la piscina no, y es imposible hundirse en agua pura.', 'El lago fue creado por el hombre y no porta naturaleza, y los humanos solo pueden flotar en aguas naturales.'],
  'Las hipótesis se juzgan por si explican lo observado. Fíjate en qué detalle del texto queda sin explicar en cada opción.', 'publicada', 'modelo', 'da37e5ffac34ca09336f732707d37860', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7f203498-c719-48b4-8f98-11e0d5f28bde', 1, 'Un cuerpo flota con más facilidad cuando el líquido en el que está es más denso que él. El color, el olor y el sabor extraños son pistas de que en esa agua hay algo disuelto, y lo disuelto aumenta la densidad; por eso empuja más hacia arriba que el agua de una piscina. Las demás no explican nada: el enunciado dice que hay 4 metros de profundidad, y ni ser potable ni ser natural tiene que ver con la densidad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '49dfe75a-8a8f-4a88-a1f3-5f5f418df281', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'ondas-y-sonido'),
  (select id from public.lotes where codigo = '2026-B'),
  '72db55ba-ede8-4cd3-946c-d74bc2f58e6e', 'Ondas y sonido',
  'Si la esfera hueca se llena con agua sucedería que',
  array['la frecuencia de oscilación del péndulo aumentaría.', 'la frecuencia de oscilación del péndulo disminuiría.', 'la frecuencia de oscilación del péndulo no cambiaría.', 'el periodo de oscilación del péndulo aumentaría.'],
  'Escribe de qué depende el periodo de un péndulo. Lo que no aparezca en esa lista, no lo afecta.', 'publicada', 'modelo', 'c76b2ea41979fae59457b35a06096d70', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('49dfe75a-8a8f-4a88-a1f3-5f5f418df281', 2, 'Llenar la esfera cambia su masa, pero el ritmo con el que oscila un péndulo no depende de la masa que cuelga: depende solo de la longitud de la cuerda y de la gravedad. Es el mismo motivo por el que dos cuerpos de distinto peso caen igual cuando se puede despreciar el aire. Como la cuerda sigue midiendo 2,5 metros, ni la frecuencia ni el periodo cambian.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fe4b66dc-81d1-4ea3-9181-a4a2fe03b065', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'ondas-y-sonido'),
  (select id from public.lotes where codigo = '2026-B'),
  '72db55ba-ede8-4cd3-946c-d74bc2f58e6e', 'Ondas y sonido',
  'Si el experimento se repitiera pero utilizando una cuerda de 10 m sucedería que',
  array['la frecuencia aumentaría al doble.', 'el periodo de oscilación disminuiría a la mitad.', 'la frecuencia de oscilación no se vería afectada.', 'la frecuencia disminuiría a la mitad.'],
  'Cuadruplicar la longitud no cuadruplica el periodo: en la fórmula la longitud está bajo una raíz.', 'publicada', 'modelo', 'e3cc00d9c6d855c1e5c44137dd27665e', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fe4b66dc-81d1-4ea3-9181-a4a2fe03b065', 3, 'El periodo de un péndulo crece con la raíz cuadrada de la longitud. Pasar de 2,5 a 10 metros es multiplicar la longitud por cuatro, y la raíz de cuatro es dos: el periodo se duplica. La frecuencia es el inverso del periodo, así que si el periodo se duplica la frecuencia se reduce a la mitad. Una cuerda más larga hace un péndulo más lento, no más rápido.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ada97394-caa1-49b5-8640-9a9e357f0a01', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'ondas-y-sonido'),
  (select id from public.lotes where codigo = '2026-B'),
  '72db55ba-ede8-4cd3-946c-d74bc2f58e6e', 'Ondas y sonido',
  'Si la longitud de onda de las ondas formadas en el agua fuera π metros (λ = π), entonces la velocidad de estas ondas sería de',
  array['π m/s', '1/π m/s', '0,5 m/s', '1 m/s'],
  'Primero saca el periodo del péndulo, de ahí la frecuencia, y solo al final multiplica por la longitud de onda.', 'publicada', 'modelo', 'aad5c6be35945202c9a714cc03622b7d', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ada97394-caa1-49b5-8640-9a9e357f0a01', 3, 'Las ondas se forman al ritmo del péndulo, así que su frecuencia es la del péndulo. Con una cuerda de 2,5 metros y una gravedad de 10 m/s², el periodo es 2π por la raíz de 2,5 entre 10, es decir 2π por 0,5, o sea π segundos. La frecuencia es entonces 1/π hercios. La velocidad de una onda es su longitud de onda por su frecuencia: π por 1/π da exactamente 1 metro por segundo. Los π se cancelan, y por eso el resultado sale redondo.');

